"""Exercise the factory filesystem with the same LittleFS library used by PlatformIO."""
import hashlib
import importlib.util
import json
from pathlib import Path
import tempfile
import unittest

from littlefs import LittleFS
from littlefs.errors import LittleFSError

spec = importlib.util.spec_from_file_location("factory_image", Path(__file__).parents[1] / "factory_image.py")
factory = importlib.util.module_from_spec(spec)
spec.loader.exec_module(factory)


class FactoryImageTests(unittest.TestCase):
    def setUp(self):
        self.temporary = tempfile.TemporaryDirectory(prefix="inter-comms-factory-")
        self.addCleanup(self.temporary.cleanup)
        self.directory = Path(self.temporary.name)
        self.sdkconfig = self.directory / "sdkconfig.h"
        self.sdkconfig.write_text("""#define CONFIG_LITTLEFS_READ_SIZE 128
#define CONFIG_LITTLEFS_WRITE_SIZE 128
#define CONFIG_LITTLEFS_CACHE_SIZE 512
#define CONFIG_LITTLEFS_LOOKAHEAD_SIZE 128
#define CONFIG_LITTLEFS_BLOCK_CYCLES 512
#define CONFIG_LITTLEFS_OBJ_NAME_LEN 64
#define CONFIG_LITTLEFS_DISK_VERSION_2_0 1
""", encoding="utf-8")
        self.config = factory.read_runtime_config(self.sdkconfig)
        self.data = bytes(range(256)) * 17
        digest = hashlib.sha256(self.data).hexdigest()
        self.path = "/inter_comms/model-" + digest[:16] + ".webp"
        self.entry = {"path": self.path, "size": len(self.data), "sha256": digest}
        self.file = self.directory / self.path.lstrip("/")
        self.file.parent.mkdir()
        self.file.write_bytes(self.data)
        self.manifest = self.directory / "manifest.json"
        self.manifest.write_text(json.dumps([self.entry]), encoding="utf-8")

    def test_serialized_filesystem_contains_exact_models_without_unlisted_configuration(self):
        (self.directory / "cfg.json").write_text('{"name":"do not package"}', encoding="utf-8")
        image = factory.build_filesystem(self.directory, 128 * 1024, self.config)
        self.assertEqual(len(image), 128 * 1024)
        factory.verify_filesystem(image, {self.path: self.data}, self.config)

    def test_damaged_package_is_rejected_before_formatting(self):
        self.file.write_bytes(bytes(len(self.data)))
        with self.assertRaisesRegex(ValueError, "damaged"):
            factory.build_filesystem(self.directory, 128 * 1024, self.config)

    def test_manifest_cannot_reference_configuration_or_escape_package_directory(self):
        for path in ("/cfg.json", "/inter_comms/../wsec.json"):
            with self.subTest(path=path):
                self.manifest.write_text(json.dumps([{**self.entry, "path": path}]), encoding="utf-8")
                with self.assertRaisesRegex(ValueError, "Invalid model manifest entry"):
                    factory.build_filesystem(self.directory, 128 * 1024, self.config)

    def test_filesystem_verification_detects_missing_or_wrong_assets(self):
        image = factory.build_filesystem(self.directory, 128 * 1024, self.config)
        with self.assertRaisesRegex(ValueError, "missing or unexpected"):
            factory.verify_filesystem(image, {}, self.config)
        with self.assertRaisesRegex(ValueError, "verification failed"):
            factory.verify_filesystem(image, {self.path: b"wrong model"}, self.config)


    def test_factory_image_mounts_with_esp32c6_runtime_version_2_0(self):
        image = factory.build_filesystem(self.directory, 128 * 1024, self.config)
        # Configure the reader independently: reusing the writer's defaults hid the original mismatch.
        reader = LittleFS(block_size=4096, block_count=len(image) // 4096,
                          read_size=128, prog_size=128, cache_size=512,
                          lookahead_size=128, block_cycles=512, name_max=64,
                          disk_version=0x00020000, mount=False)
        reader.context.buffer = bytearray(image)
        reader.mount()
        try:
            with reader.open(self.path, "rb") as source:
                self.assertEqual(source.read(), self.data)
        finally:
            reader.unmount()

    def test_runtime_verification_rejects_incompatible_version_2_1(self):
        newer = {**self.config, "disk_version": 0x00020001}
        image = factory.build_filesystem(self.directory, 128 * 1024, newer)
        with self.assertRaises(LittleFSError):
            factory.verify_filesystem(image, {self.path: self.data}, self.config)

    def test_sdk_configuration_is_required_instead_of_assuming_a_disk_version(self):
        self.sdkconfig.write_text("#define CONFIG_LITTLEFS_READ_SIZE 128\n", encoding="utf-8")
        with self.assertRaisesRegex(ValueError, "Missing or invalid"):
            factory.read_runtime_config(self.sdkconfig)


if __name__ == "__main__":
    unittest.main()
